    found.sort_by(|a, b| b.0.cmp(&a.0).then_with(|| a.1.to_lowercase().cmp(&b.1.to_lowercase())));
    for (_, name, cmd) in found {
        add(name, cmd, &mut apps);
    }
    if apps.is_empty() {
        for (n, c) in [("Kate", "kate"), ("KWrite", "kwrite")] {
