        let mut y = MARGIN_Y;
        for r in rows {
            if r < 0.0 {
                out.push((y, y)); // checkbox row
                y += LINE + MARGIN_Y;
                continue;
            }
            let box_y = y + LINE + MARGIN_Y;
            out.push((y, box_y));
            y = box_y + r * LINE + 8.0 + MARGIN_Y;
