        } else {
            p.line_segment([pos2(rect.right() - 17.0, rect.top() + 2.0), pos2(rect.right() - 17.0, rect.bottom() - 2.0)], Stroke::new(1.0, Color32::from_rgb(0xE8, 0xE8, 0xE8)));
        }
    }

    pub fn ui(&mut self, ui: &mut Ui, _shared: &mut Shared) -> Vec<Action> {
        let ctx = ui.ctx().clone();
